function main({
  product_requests_json,
  missing_fields_json,
  clarification_needed_text,
  follow_up_intent,
  scope_status,
  user_question,
  stored_product_requests
}) {
  let product_requests = [];
  let missing_fields = [];

  // --------------------------------------------------
  // 1. Parse extraction outputs
  // --------------------------------------------------

  try {
    const parsedProducts = JSON.parse(product_requests_json || "[]");
    product_requests = Array.isArray(parsedProducts)
      ? parsedProducts
      : [];
  } catch (e) {
    product_requests = [];
  }

  try {
    const parsedMissing = JSON.parse(missing_fields_json || "[]");
    missing_fields = Array.isArray(parsedMissing)
      ? parsedMissing
      : [];
  } catch (e) {
    missing_fields = [];
  }

  let clarification_needed =
    String(clarification_needed_text || "")
      .trim()
      .toLowerCase() === "true";

  let normalizedIntent =
    String(follow_up_intent || "none")
      .trim()
      .toLowerCase();

  let normalizedScope =
    String(scope_status || "unrelated")
      .trim()
      .toLowerCase();

  const storedRequests =
    Array.isArray(stored_product_requests)
      ? stored_product_requests
      : [];

  const question =
    String(user_question || "")
      .trim()
      .toLowerCase();


  // --------------------------------------------------
  // 2. Supported category whitelist
  // --------------------------------------------------

  const supportedCategories = {
    laptop: "Laptop",
    desktop: "Desktop",
    smartphone: "Smartphone",
    tablet: "Tablet",
    headphones: "Headphones",
    monitor: "Monitor",
    smartwatch: "Smartwatch",
    mouse: "Mouse",
    keyboard: "Keyboard"
  };


  // --------------------------------------------------
  // 3. Deterministically detect common follow-up intent
  // --------------------------------------------------

  let detectedIntent = "none";

  if (
    /\bcheaper\b/.test(question) ||
    /\bmore affordable\b/.test(question) ||
    /\bless expensive\b/.test(question) ||
    /\blower[- ]priced\b/.test(question)
  ) {
    detectedIntent = "cheaper";
  } else if (
    /\bmore expensive\b/.test(question) ||
    /\bhigher[- ]priced\b/.test(question)
  ) {
    detectedIntent = "more_expensive";
  } else if (
    /\balternative\b/.test(question) ||
    /\banother (one|option|product)\b/.test(question) ||
    /\bdifferent (one|option|product)\b/.test(question) ||
    /\bother option\b/.test(question)
  ) {
    detectedIntent = "alternative";
  }

  const effectiveIntent =
    detectedIntent !== "none"
      ? detectedIntent
      : normalizedIntent;

  const isFollowUp =
    effectiveIntent === "cheaper" ||
    effectiveIntent === "more_expensive" ||
    effectiveIntent === "alternative";


  // --------------------------------------------------
  // 4. Follow-up state guard
  // --------------------------------------------------
  //
  // A short contextual follow-up such as:
  // "Can you recommend a cheaper option?"
  // must continue the previous supported request.
  // --------------------------------------------------

  if (isFollowUp && storedRequests.length > 0) {
    normalizedIntent = effectiveIntent;

    normalizedScope = "supported";

    // Restore previous product state if the extractor lost it.
    if (product_requests.length === 0) {
      product_requests = storedRequests.map(item => ({
        ...item
      }));
    }

    missing_fields = getMissingFields(product_requests);

    clarification_needed =
      missing_fields.length > 0;
  }


  // --------------------------------------------------
  // 5. Category whitelist guard
  // --------------------------------------------------
  //
  // Supported categories are a hard business rule.
  // If the extractor returns Camera, TV, Printer, Router, etc.,
  // the request must be routed to unsupported instead of asking
  // clarification questions.
  // --------------------------------------------------

  let hasUnsupportedCategory = false;

  product_requests = product_requests.map(request => {
    if (!request || typeof request !== "object") {
      return request;
    }

    const rawCategory =
      String(request.category || "").trim();

    if (!rawCategory) {
      return request;
    }

    const canonicalCategory =
      supportedCategories[rawCategory.toLowerCase()];

    if (!canonicalCategory) {
      hasUnsupportedCategory = true;
      return request;
    }

    return {
      ...request,
      category: canonicalCategory
    };
  });

  if (hasUnsupportedCategory) {
    normalizedScope = "unsupported";
    normalizedIntent = "none";
    clarification_needed = false;
    missing_fields = [];
  }


  // --------------------------------------------------
  // 6. Recalculate missing fields for supported requests
  // --------------------------------------------------

  if (
    normalizedScope === "supported" &&
    product_requests.length > 0
  ) {
    missing_fields = getMissingFields(product_requests);

    clarification_needed =
      missing_fields.length > 0;
  }


  // --------------------------------------------------
  // 7. Normalize allowed intent values
  // --------------------------------------------------

  const allowedIntents = [
    "none",
    "cheaper",
    "more_expensive",
    "alternative"
  ];

  if (!allowedIntents.includes(normalizedIntent)) {
    normalizedIntent = "none";
  }


  // --------------------------------------------------
  // 8. Normalize allowed scope values
  // --------------------------------------------------

  const allowedScopes = [
    "supported",
    "unsupported",
    "help",
    "unrelated"
  ];

  if (!allowedScopes.includes(normalizedScope)) {
    normalizedScope = "unrelated";
  }


  // --------------------------------------------------
  // 9. Return normalized state
  // --------------------------------------------------

  return {
    product_requests,
    missing_fields,
    clarification_needed,
    follow_up_intent: normalizedIntent,
    scope_status: normalizedScope
  };


  // --------------------------------------------------
  // Helper: determine missing required fields
  // --------------------------------------------------

  function getMissingFields(requests) {
    const missing = new Set();

    for (const request of requests) {
      if (
        !request ||
        !String(request.category || "").trim()
      ) {
        missing.add("category");
      }

      if (
        request == null ||
        request.budget === null ||
        request.budget === undefined ||
        String(request.budget).trim() === ""
      ) {
        missing.add("budget");
      }

      if (
        !request ||
        !String(request.main_usage || "").trim()
      ) {
        missing.add("main_usage");
      }
    }

    return Array.from(missing);
  }
}

