function main({
  raw_json,
  active_requests,
  previous_recommendations,
  follow_up_intent
}) {
  let text = String(raw_json || "").trim();

  text = text
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  let data;

  try {
    data = JSON.parse(text);
  } catch (e) {
    const firstBrace = text.indexOf("{");
    const lastBrace = text.lastIndexOf("}");

    if (firstBrace !== -1 && lastBrace > firstBrace) {
      try {
        data = JSON.parse(text.slice(firstBrace, lastBrace + 1));
      } catch (e2) {
        return invalidResult(
          "Invalid JSON returned by the recommendation model."
        );
      }
    } else {
      return invalidResult(
        "Invalid JSON returned by the recommendation model."
      );
    }
  }

  const answer =
    typeof data.answer === "string" ? data.answer : "";

  const recommendations =
    Array.isArray(data.recommendations)
      ? data.recommendations
      : [];

  const next_step =
    typeof data.next_step === "string"
      ? data.next_step
      : "";

  // Recommendation branch = required information already complete.
  const clarification_needed = false;

  const requests =
    Array.isArray(active_requests)
      ? active_requests
      : [];

  const previous =
    Array.isArray(previous_recommendations)
      ? previous_recommendations
      : [];

  const intent =
    String(follow_up_intent || "none")
      .trim()
      .toLowerCase();

  /*
   * Static validation catalogue for the current MyTech classroom prototype.
   * The knowledge base remains the recommendation source.
   * This catalogue is only a deterministic safety layer for validating
   * product identity, category, reference price and source.
   */
  const PRODUCT_CATALOG = {
    "Lenovo Xiaoxin 14 (2025, Ryzen 7 H255, 16GB/512GB)": {
      category: "Laptop",
      price: 5799,
      source: "Lenovo Official Store"
    },
    "HUAWEI MateBook 14": {
      category: "Laptop",
      price: 6599,
      source: "Huawei Official Website"
    },
    "Lenovo Xiaoxin Pro 14 (Ryzen 7 H255, 32GB/1TB)": {
      category: "Laptop",
      price: 8999,
      source: "Lenovo Official Store"
    },

    "Lenovo Tianyi 510S (Core i3-14100, 16GB/512GB)": {
      category: "Desktop",
      price: 4099,
      source: "Lenovo Official Store"
    },
    "Lenovo Tianyi 510S (Core i5-14400, 16GB/512GB)": {
      category: "Desktop",
      price: 5099,
      source: "Lenovo Official Store"
    },
    "Apple Mac mini (M4 Pro)": {
      category: "Desktop",
      price: 10999,
      source: "Apple China"
    },

    "HUAWEI nova 14 活力版": {
      category: "Smartphone",
      price: 2399,
      source: "Huawei Official Website"
    },
    "HONOR 400 Pro (12GB/256GB)": {
      category: "Smartphone",
      price: 3399,
      source: "HONOR Official Launch Information"
    },
    "Apple iPhone 17 (256GB)": {
      category: "Smartphone",
      price: 6799,
      source: "Apple China"
    },

    "HUAWEI MatePad 11.5 S (2025)": {
      category: "Tablet",
      price: 2199,
      source: "Huawei Official Website"
    },
    "HUAWEI MatePad 11.5 (2026)": {
      category: "Tablet",
      price: 2599,
      source: "Huawei Official Website"
    },
    "Apple iPad Air 11-inch (M3, Wi-Fi)": {
      category: "Tablet",
      price: 4799,
      source: "Apple China"
    },

    "Sony WH-CH520": {
      category: "Headphones",
      price: 350,
      source: "Sony / JD Reference"
    },
    "Apple AirPods Pro 3": {
      category: "Headphones",
      price: 1899,
      source: "Apple China"
    },
    "Sony WH-1000XM6": {
      category: "Headphones",
      price: 4799,
      source: "Sony China"
    },

    "AOC Q27G40E": {
      category: "Monitor",
      price: 879,
      source: "AOC China Official Store"
    },
    "REDMI G27Q 320Hz": {
      category: "Monitor",
      price: 1199,
      source: "JD / Market Reference"
    },
    "LG UltraGear 27GS95QE": {
      category: "Monitor",
      price: 3499,
      source: "LG China / Market Reference"
    },

    "HUAWEI WATCH GT 5 (41mm)": {
      category: "Smartwatch",
      price: 1488,
      source: "Huawei Official Website"
    },
    "Apple Watch SE 3": {
      category: "Smartwatch",
      price: 1999,
      source: "Apple China"
    },
    "HUAWEI WATCH 5": {
      category: "Smartwatch",
      price: 2699,
      source: "Huawei Official Website"
    },

    "Logitech M240": {
      category: "Mouse",
      price: 109,
      source: "JD Reference"
    },
    "Logitech G304 LIGHTSPEED": {
      category: "Mouse",
      price: 229,
      source: "JD / Market Reference"
    },
    "Logitech MX Master 3S": {
      category: "Mouse",
      price: 429,
      source: "Logitech / Market Reference"
    },

    "Logitech K848": {
      category: "Keyboard",
      price: 249,
      source: "JD / Market Reference"
    },
    "Logitech Signature K650": {
      category: "Keyboard",
      price: 299,
      source: "Logitech / JD Reference"
    },
    "Logitech MX Keys S": {
      category: "Keyboard",
      price: 529,
      source: "Logitech / JD Reference"
    }
  };

  let validation_ok = true;
  let validation_error = "";

  const seenCategories = new Set();

  // Do not allow more recommendations than active product requests.
  if (recommendations.length > requests.length) {
    return invalidResult(
      "Validation violation: more recommendations were returned than active product requests."
    );
  }

  for (const rec of recommendations) {
    if (!rec || typeof rec !== "object") {
      validation_ok = false;
      validation_error =
        "Validation violation: recommendation must be an object.";
      break;
    }

    const productName =
      typeof rec.recommended_product === "string"
        ? rec.recommended_product.trim()
        : "";

    const recCategory =
      typeof rec.category === "string"
        ? rec.category.trim()
        : "";

    const recSource =
      typeof rec.source === "string"
        ? rec.source.trim()
        : "";

    const price = Number(rec.price);

    // 1. Product identity validation
    const approvedProduct = PRODUCT_CATALOG[productName];

    if (!approvedProduct) {
      validation_ok = false;
      validation_error =
        `Product validation violation: "${productName || "Unknown product"}" ` +
        `is not an approved MyTech product.`;
      break;
    }

    // 2. Product-category validation
    if (
      approvedProduct.category.toLowerCase() !==
      recCategory.toLowerCase()
    ) {
      validation_ok = false;
      validation_error =
        `Category validation violation: "${productName}" is a ` +
        `${approvedProduct.category}, not a ${recCategory || "missing category"}.`;
      break;
    }

    // 3. Active-request category validation
    const request = requests.find(
      r =>
        String(r.category || "")
          .trim()
          .toLowerCase() ===
        approvedProduct.category.toLowerCase()
    );

    if (!request) {
      validation_ok = false;
      validation_error =
        `Category validation violation: "${productName}" belongs to ` +
        `${approvedProduct.category}, but there is no active request for that category.`;
      break;
    }

    // 4. Prevent duplicate recommendations for the same category
    const categoryKey =
      approvedProduct.category.toLowerCase();

    if (seenCategories.has(categoryKey)) {
      validation_ok = false;
      validation_error =
        `Validation violation: multiple recommendations were returned for ` +
        `${approvedProduct.category}.`;
      break;
    }

    seenCategories.add(categoryKey);

    // 5. Exact reference-price validation
    if (
      !Number.isFinite(price) ||
      price !== approvedProduct.price
    ) {
      validation_ok = false;
      validation_error =
        `Price validation violation: "${productName}" must use the approved ` +
        `reference price of ¥${approvedProduct.price}.`;
      break;
    }

    // 6. Exact source validation
    if (recSource !== approvedProduct.source) {
      validation_ok = false;
      validation_error =
        `Source validation violation: "${productName}" must use the approved ` +
        `source "${approvedProduct.source}".`;
      break;
    }

    // 7. Hard-budget validation
    const budget = Number(request.budget);

    if (
      Number.isFinite(budget) &&
      price > budget
    ) {
      validation_ok = false;
      validation_error =
        `Budget violation: ${productName} costs ¥${price}, ` +
        `but the active budget is ¥${budget}.`;
      break;
    }

    // Find previous recommendation using the verified category,
    // not the model-provided category alone.
    const previousRec = previous.find(
      r =>
        String(r.category || "")
          .trim()
          .toLowerCase() ===
        approvedProduct.category.toLowerCase()
    );

    // 8. Follow-up validation
    if (previousRec) {
      const previousPrice = Number(previousRec.price);

      if (
        intent === "cheaper" &&
        Number.isFinite(previousPrice) &&
        price >= previousPrice
      ) {
        validation_ok = false;
        validation_error =
          "Follow-up violation: cheaper recommendation must cost less than the previous recommendation.";
        break;
      }

      if (
        intent === "more_expensive" &&
        Number.isFinite(previousPrice) &&
        price <= previousPrice
      ) {
        validation_ok = false;
        validation_error =
          "Follow-up violation: more_expensive recommendation must cost more than the previous recommendation.";
        break;
      }

      if (
        intent === "alternative" &&
        productName.toLowerCase() ===
        String(previousRec.recommended_product || "")
          .trim()
          .toLowerCase()
      ) {
        validation_ok = false;
        validation_error =
          "Follow-up violation: alternative recommendation must be a different product.";
        break;
      }

      if (
        intent === "cheaper" ||
        intent === "more_expensive" ||
        intent === "alternative"
      ) {
        const previousCategory =
          String(previousRec.category || "")
            .trim()
            .toLowerCase();

        if (
          previousCategory &&
          previousCategory !==
            approvedProduct.category.toLowerCase()
        ) {
          validation_ok = false;
          validation_error =
            "Follow-up category violation: follow-up recommendations must remain in the same product category.";
          break;
        }
      }
    }
  }

  const normalized = {
    answer,
    recommendations,
    next_step,
    clarification_needed
  };

  return {
    answer,
    recommendations,
    next_step,
    clarification_needed,
    validation_ok,
    validation_error,
    normalized_json: JSON.stringify(normalized)
  };

  function invalidResult(message) {
    return {
      answer: "",
      recommendations: [],
      next_step: "",
      clarification_needed: false,
      validation_ok: false,
      validation_error: message,
      normalized_json: ""
    };
  }
}

