function main({
  user_question,
  active_requests,
  follow_up_intent,
  previous_recommendations
}) {
  const requests = Array.isArray(active_requests) ? active_requests : [];
  const previous = Array.isArray(previous_recommendations)
    ? previous_recommendations
    : [];

  const queries = requests.map((request, index) => {
    const category = request?.category || "";
    const budget = request?.budget ?? "";
    const mainUsage = request?.main_usage || "";

    const previousItem = previous[index] || previous.find(
      item => item?.category === category
    );

    const previousProduct = previousItem?.recommended_product || "";
    const previousPrice = previousItem?.price ?? "";

    return [
      `User request: ${user_question || ""}`,
      `Active category: ${category}`,
      budget !== "" ? `Hard budget: RMB ${budget}` : "",
      mainUsage ? `Main usage: ${mainUsage}` : "",
      `Follow-up intent: ${follow_up_intent || "none"}`,
      previousProduct ? `Previous recommendation: ${previousProduct}` : "",
      previousPrice !== "" ? `Previous price: RMB ${previousPrice}` : "",
      `Retrieve products from the SAME category: ${category}`
    ]
      .filter(Boolean)
      .join(". ");
  });

  return {
    retrieval_queries:
      queries.length > 0
        ? queries
        : [String(user_question || "")]
  };
}
